CREATE TABLE IF NOT EXISTS panas_accounting_buyers (buyer_id uuid PRIMARY KEY, public_key_pem text NOT NULL, enabled boolean NOT NULL DEFAULT true, balance numeric(30,0) NOT NULL DEFAULT 0 CHECK(balance>=0), held numeric(30,0) NOT NULL DEFAULT 0 CHECK(held>=0 AND held<=balance), max_request numeric(30,0) NOT NULL CHECK(max_request>=0), max_session numeric(30,0) NOT NULL CHECK(max_session>=0), max_daily numeric(30,0) NOT NULL CHECK(max_daily>=0), policy_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
